use anyhow::Result;

pub struct Row {
    pub id: u64,
    pub email: String,
}

fn copy_row(row: &Row) -> Result<()> {
    if !row.email.contains('@') {
        anyhow::bail!("row {} has no valid email", row.id);
    }
    std::thread::sleep(std::time::Duration::from_millis(5));
    Ok(())
}

pub fn migrate(rows: &[Row]) -> Result<usize> {
    let mut copied = 0;
    for row in rows {
        copy_row(row)?;
        copied += 1;
    }
    Ok(copied)
}

