use indicatif::{ProgressBar, ProgressStyle};

pub fn migrate(rows: &[Row]) -> Result<usize> {
    let bar = ProgressBar::new(rows.len() as u64);
    bar.set_style(
        ProgressStyle::with_template("{elapsed_precise} [{bar:40.cyan/blue}] {pos}/{len} ({eta})")?
            .progress_chars("=> "),
    );
    let mut copied = 0;
    for row in rows {
        copy_row(row)?;
        copied += 1;
        bar.inc(1);
    }
    bar.finish_with_message(format!("copied {copied} rows"));
    Ok(copied)
}

